(()=>{window.resolveProjectionYears=3;document.querySelectorAll('[data-projection-years]').forEach(b=>b.addEventListener('click',()=>{window.resolveProjectionYears=Number(b.dataset.projectionYears);document.querySelectorAll('[data-projection-years]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));document.getElementById('projection-period-note').textContent='Cumulative totals through year '+window.resolveProjectionYears;document.dispatchEvent(new Event('resolve-model'));}));})();